{% doc %}
  Fulldev UI rating styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-rating.css' | asset_url | stylesheet_tag }}

[data-slot='rating'] {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing);
  color: var(--primary);
}
.rating__star {
  position: relative;
  display: inline-flex;
  width: calc(var(--spacing) * 4);
  height: calc(var(--spacing) * 4);
  color: color-mix(in oklch, var(--muted-foreground) 25%, transparent);
}
.rating__star svg {
  width: 100%;
  height: 100%;
}
.rating__fill {
  position: absolute;
  inset: 0;
  overflow: hidden;
  color: var(--primary);
}
